let battlegroupsData=null,battlegroupsBusy=false;
async function loadBattlegroups(){const box=document.getElementById('battlegroupsBoard');if(!box)return;try{battlegroupsData=await centralDirectoryRequest('/api/battlegroups');if(!box.isConnected)return;const d=battlegroupsData,memberName=id=>d.members.find(m=>m.id===id)?.username||'Former alliance member';
 box.innerHTML='<div class="bg-intro"><h3>Alliance battlegroups</h3><p>Organise teams, approve members and transfer command. Rankings use current registered planet scores. Requests do not count as members.</p><button class="btn" data-bg-action="refresh">REFRESH</button><p id="bgStatus" role="status"></p></div><form id="battlegroupCreate" class="bg-create"><label>Group name<input name="name" maxlength="80" required></label><label>Description<textarea name="description" maxlength="2000"></textarea></label><button class="btn">CREATE BATTLEGROUP</button></form><div class="bg-grid">'+d.groups.map((g,i)=>{const own=g.ownerId===d.userId,manage=own||d.canManage,mine=g.members.find(m=>m.userId===d.userId),btn=(action,label,userId='')=>'<button class="btn" data-bg-action="'+action+'" data-bg-id="'+esc(g.id)+'" data-bg-user="'+esc(userId)+'">'+label+'</button>';return '<section class="panel bg-card"><div class="ph"><b>#'+(i+1)+' · '+esc(g.name)+'</b><span>'+Number(g.score).toLocaleString()+' score</span></div><div class="bg-body"><p>'+esc(g.description)+'</p><small>Commander: '+esc(memberName(g.ownerId))+' · '+g.planetCount+' registered planets</small><ul>'+g.members.map(m=>'<li><span>'+esc(memberName(m.userId))+' · '+esc(m.status)+(m.userId===g.ownerId?' · Commander':'')+'</span><div class="controls">'+(manage&&m.userId!==g.ownerId?(m.status==='requested'?btn('approve','APPROVE',m.userId)+btn('decline','DECLINE',m.userId):btn('remove','REMOVE',m.userId)):'')+(own&&m.userId!==d.userId&&m.status==='accepted'?btn('transfer','TRANSFER COMMAND',m.userId):'')+'</div></li>').join('')+'</ul><div class="controls">'+(!mine?btn('join','REQUEST TO JOIN'):!own?btn('leave',mine.status==='requested'?'WITHDRAW REQUEST':'LEAVE GROUP'):'')+(manage?btn('disband','DISBAND GROUP'):'')+'</div>'+(manage?'<form class="bg-edit" data-bg-id="'+esc(g.id)+'"><label>Name<input name="name" maxlength="80" value="'+esc(g.name)+'" required></label><label>Description<textarea name="description" maxlength="2000">'+esc(g.description)+'</textarea></label><button class="btn">SAVE GROUP</button></form>':'')+'</div></section>';}).join('')+'</div>'+(d.groups.length?'':'<p>No battlegroups in this alliance yet.</p>');}catch(e){box.textContent=e.message;}}
async function battlegroupPost(body){if(battlegroupsBusy||!battlegroupsData)return;battlegroupsBusy=true;try{await centralDirectoryRequest('/api/battlegroups',{...body,generation:battlegroupsData.generation,revision:battlegroupsData.revision});await loadBattlegroups();notify('Battlegroup updated.');}catch(e){const status=document.getElementById('bgStatus');if(status)status.textContent=e.message;}finally{battlegroupsBusy=false;}}
document.addEventListener('click',e=>{const b=e.target.closest('[data-bg-action]');if(!b)return;const action=b.dataset.bgAction;if(action==='refresh'){loadBattlegroups();return;}if(['disband','transfer','remove'].includes(action)&&!confirm('Confirm '+action+'?'))return;battlegroupPost({action,groupId:b.dataset.bgId,userId:b.dataset.bgUser});});
document.addEventListener('submit',e=>{if(e.target.id!=='battlegroupCreate'&&!e.target.matches('.bg-edit'))return;e.preventDefault();const f=new FormData(e.target);battlegroupPost({action:e.target.id==='battlegroupCreate'?'create':'edit',groupId:e.target.dataset.bgId,name:f.get('name'),description:f.get('description')});});
